SELECT w.*
FROM (

) w
WHERE w.work_date BETWEEN #{startDate} AND #{endDate}
AND w.org_type = #{orgType}
AND w.org_id = #{orgId}
AND w.staff_type = #{staffType}
AND w.employee_id = #{employeeId}
AND w.diff_type = #{diffType}
ORDER BY w.work_date, w.org_type, w.org_id, w.employee_id

SELECT s.*
FROM (

) s
WHERE s.work_date BETWEEN #{startDate} AND #{endDate}
AND s.org_type = #{orgType}
AND s.org_id = #{orgId}
AND s.staff_type = #{staffType}
ORDER BY s.work_date, s.org_type, s.org_id

SELECT a.*
FROM (

) a
WHERE 1 = 1
AND a.org_type = #{orgType}
AND a.org_id = #{orgId}
AND a.staff_type = #{staffType}
ORDER BY FIELD(a.advice_type, 1, 3, 4, 2), a.unrecorded_head_days DESC
